	FROM Dep_CustPTGroupSetting_Member a WITH(ROWLOCK,UPDLOCK)
		INNER JOIN #Dep_CustPTGroupSetting_Member t ON a.AgentID = t.AgentID AND a.SportType = t.SportType and a.BetType = t.BetType 

