	FROM Dep_CustBetSetting_Agent a WITH(ROWLOCK,UPDLOCK)
	INNER JOIN #Dep_CustBetSetting_Agent t ON a.CustID = t.CustID AND a.SportType = t.SportType and a.BetType = t.BetType 

