		INNER JOIN @SportBettype t ON a.SportType = t.SportType and a.BetType = t.BetType
		INNER JOIN CustInfo ci WITH(NOLOCK) ON a.CustID = ci.custid
		INNER JOIN #supers s ON ci.srecommend = s.custid

